    X_scale=None,
    sample_weight_sqrt=None,
):
    if sample_weight_sqrt is None:
        sample_weight_sqrt = np.ones(X.shape[0], dtype=X.dtype)
    n_samples, n_features = X.shape
    if X_offset is None or X_scale is None:
        X1 = sp_linalg.aslinearoperator(X)
