    if scipy_1_10:
        use_sparse = self.sparse_output
        kwargs_extrapolate = {"extrapolate": self.bsplines_[0].extrapolate}
    else:
        use_sparse = self.sparse_output and not self.bsplines_[0].extrapolate
        kwargs_extrapolate = dict()
